import{z as i,x as A,o as E,c as d,q as r,j as s,D as e,d as B,s as l,S as o,b as t}from"./chunks/framework.C8m1ZpeB.js";const H=JSON.parse('{"title":"HP 滤波与周期分离","description":"","frontmatter":{"title":"HP 滤波与周期分离","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/hp-filter-cycles.md","filePath":"econ/hp-filter-cycles.md","lastUpdated":1791413859000}'),p={name:"econ/hp-filter-cycles.md"};function m(P,a,c,h,F,C){const n=A("Mermaid");return E(),d("div",null,[a[2]||(a[2]=r('<h1 id="hp-滤波与周期分离" tabindex="-1">HP 滤波与周期分离 <a class="header-anchor" href="#hp-滤波与周期分离" aria-label="Permalink to &quot;HP 滤波与周期分离&quot;">​</a></h1><div class="epigraph"><p>把序列拆成光滑趋势与周期，才能谈「波动的标准差」；λ 的选择是定义，不是从数据估出来的自然常数。</p><footer>—— Hodrick and Prescott, Postwar U.S. Business Cycles: An Empirical Investigation, JMCB 1997；对照 Ravn–Uhlig 对 λ 的讨论；Hamilton 2018 的批评</footer></div><p><a href="/econ/dsge-bayesian-estimation">上一课</a>的似然吃的是模型自己的趋势假设。校准传统吃的是滤波后的周期矩。本课缺口是<strong>切开</strong>：HP 滤波做什么、与模型去趋势如何错位。不重写 Kalman，不把滤波当因果识别。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Hodrick–Prescott：\\(\\min_{\\{\\tau_t\\}}\\sum (y_t-\\tau_t)^2+\\lambda\\sum(\\Delta^2\\tau_t)^2\\)。\\(\\lambda=1600\\) 对季度是惯例。周期 \\(c_t=y_t-\\tau_t\\) 的标准差、相关、谱，成为 RBC/NK 校准的靶。缺口是：趋势是平滑器的输出，不是理论中的随机趋势或确定性时间趋势。Hamilton（2018）指出 HP 会在两端产生虚假动态、把预测误差的结构强加给周期。本课要把「周期事实」的测量声明为滤波依赖。</p><p><span class="marginnote">Hodrick and Prescott, <em>JMCB</em> 29(1), 1997（工作论文更早）。Ravn and Uhlig, <em>ReStat</em> 2002 讨论频率与 λ。Baxter–King 带通是另一刀。</span></p><p><span class="marginnote">数字实例：同一份季度 GDP，用惯例 λ=1600 与用年度尺度换算的更大 λ（Ravn–Uhlig 建议 λ 随数据频率的四次方调整）切出的「趋势」并不相同，周期标准差和相关也随之变。所以报告「产出波动 2%」时必须同时报滤波与 λ，否则数字不可比。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对对数产出、消费、投资、工时分别 HP，再算相对产出的波动与同期相关。线性 DSGE 的理论矩应对<strong>同一滤波算子</strong>施加于模型模拟，而不是拿模型的 \\(\\mathrm{Var}(\\hat y_t)\\) 直接对 HP 后的数据。若模型含单位根或漂移，HP 与一阶差分、线性趋势会给出不同靶。估计课若用增长平稳或差分平稳，与校准课的 HP 矩不要混报成同一检验。</p>',9)),(E(),s(o,null,{default:e(()=>[l(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E5%8E%9F%E5%BA%8F%E5%88%97%22%5D%20--%3E%20HP%5B%22HP%3A%20%E8%B6%8B%E5%8A%BF%20%2B%20%E5%91%A8%E6%9C%9F%22%5D%0A%20%20HP%20--%3E%20MOM%5B%22%E5%91%A8%E6%9C%9F%E7%9F%A9%22%5D%0A%20%20MOD%5B%22%E6%A8%A1%E5%9E%8B%E6%A8%A1%E6%8B%9F%22%5D%20--%3E%20HP2%5B%22%E5%90%8C%E4%B8%80%E6%BB%A4%E6%B3%A2%22%5D%0A%20%20HP2%20--%3E%20CMP%5B%22%E5%AF%B9%E7%9F%A9%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"带通（Baxter–King）、一阶差分、Hamilton 回归，是不同的周期定义。事实表必须标注刀法。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[B("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"机制是惩罚二阶差分：λ 大则趋势更直、周期更像原序列的偏离。商业周期的「4–32 季度」故事与 λ=1600 大致对齐，但不是定理。滤波是双边的（用未来 \\(y\\)），实时政策监控要用单边版本，端点问题更重。把 HP 周期当结构冲击的实现，是把平滑器当识别——后课 SVAR 才谈冲击。",-1)),(E(),s(o,null,{default:e(()=>[l(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBJ%5B%22HP%20%E7%9B%AE%E6%A0%87%EF%BC%9A%E6%8B%9F%E5%90%88%E8%AF%AF%E5%B7%AE%20%2B%20%CE%BB%20%C3%97%20%E5%BC%AF%E6%9B%B2%E6%83%A9%E7%BD%9A%22%5D%20--%3E%20FIT%5B%22%E6%8B%9F%E5%90%88%E9%A1%B9%EF%BC%9A%E8%B6%8B%E5%8A%BF%E5%B0%BD%E9%87%8F%E8%B4%B4%E4%BD%8F%E6%95%B0%E6%8D%AE%22%5D%0A%20%20OBJ%20--%3E%20PEN%5B%22%E6%83%A9%E7%BD%9A%E9%A1%B9%EF%BC%9A%E8%B6%8B%E5%8A%BF%E4%B8%8D%E8%AE%B8%E4%B9%B1%E6%8B%90%E5%BC%AF%22%5D%0A%20%20FIT%20--%3E%20S0%5B%22%CE%BB%20%E8%B6%8A%E5%B0%8F%EF%BC%9A%E8%B6%8B%E5%8A%BF%E8%B6%8A%E8%B4%B4%E6%95%B0%E6%8D%AE%EF%BC%8C%E5%91%A8%E6%9C%9F%E8%B6%8A%E7%A9%BA%22%5D%0A%20%20PEN%20--%3E%20S1%5B%22%CE%BB%20%E8%B6%8A%E5%A4%A7%EF%BC%9A%E8%B6%8B%E5%8A%BF%E8%B6%8A%E7%9B%B4%EF%BC%8C%E5%91%A8%E6%9C%9F%E5%90%83%E4%B8%8B%E5%85%A8%E9%83%A8%E6%B3%A2%E5%8A%A8%22%5D%0A%20%20S0%20--%3E%20M%5B%22%CE%BB%20%3D%201600%EF%BC%9A%E5%AD%A3%E5%BA%A6%E6%95%B0%E6%8D%AE%E7%9A%84%E6%8A%98%E4%B8%AD%E6%83%AF%E4%BE%8B%22%5D%0A%20%20S1%20--%3E%20M%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">直觉类比：HP 像用一根有弹性的尺子沿 GDP 曲线描趋势。λ 小，尺子软，能贴着每个弯走；λ 大，尺子硬邦邦，只能描出一条近乎直线，剩下的起伏全被算成「周期」。</span></p><p>增长理论里的趋势是 TFP 与资本；HP 趋势不必等于 Solow 残差的累积。混为一谈会让「周期劳动份额」变成滤波伪迹。</p><p><span class="marginnote">常见误区：初学者容易把 HP 趋势当成「潜在产出」。它只是平滑器的输出，而且用未来数据：一场疫情深坑会立刻改写之前几年的「趋势」。实时决策若照抄 HP 趋势，会把刚发生的冲击误读成普通的周期偏离。</span></p><p><span class="marginnote">Kydland–Prescott 的矩表默认 HP。Smets–Wouters 估计常对数据做去趋势或用增长观测，两套传统的「拟合」不可直接比大小。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列各国事实表（下一课）。不把 λ 写成最优政策参数。也不进入频谱计量的全部工具。资产价格的「周期」更不宜默认 HP：估值比率有持久成分，那是另一课程已写的回报可预测，本栏不重做。</p><p>后课默认：周期矩必须声明滤波；模型矩用同一算子。下一课：在 HP（或标明的刀）下，商业周期事实是哪些共动。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HP 用平滑惩罚定义趋势；λ 是惯例。</li><li>模型与数据必须过同一滤波才能对矩。</li><li>滤波不是冲击识别；端点与虚假动态是已知代价。</li><li>出处：Hodrick and Prescott, <em>JMCB</em> 1997；Hamilton, <em>ReStat</em> 2018。</li></ul>',9))])}const _=i(p,[["render",m]]);export{H as __pageData,_ as default};
